manager = read("manager.py")
import_anchor = "from packaging.version import InvalidVersion, Version\n"
if "from factorio_settings import (" not in manager:
    manager = manager.replace(import_anchor, import_anchor + '''from factorio_settings import (\n    SETTINGS_STAGE_FILES,\n    SettingsCodecError,\n    coerce_setting_value,\n    infer_prototype_type,\n    read_mod_settings,\n    read_settings_stage_sources,\n    scan_setting_prototypes,\n    set_document_setting,\n    setting_name_likely_belongs_to_mod,\n    settings_values,\n    write_mod_settings,\n)\n''')

