app = read("app.py")
if 'def get_mod_settings()' not in app:
    marker = '@app.post("/api/mod/open-location")\ndef open_mod_location():'
    routes = '''@app.get("/api/mod/settings")\ndef get_mod_settings():\n    try:\n        return ok(settings=manager.mod_settings_state(request.args.get("mod", "")))\n    except ManagerError as exc:\n        return fail(exc)\n\n\n@app.post("/api/mod/settings")\ndef save_mod_settings():\n    try:\n        payload = request.get_json(silent=True) or {}\n        return ok(result=manager.save_mod_settings(payload.get("mod", ""), payload.get("changes") or {}))\n    except ManagerError as exc:\n        return fail(exc)\n\n\n'''
    if marker not in app:
        raise RuntimeError("app mod location marker not found")
    app = app.replace(marker, routes + marker)
write("app.py", app)


